def _glom_match(target, spec, scope):
    if isinstance(spec, type):
        if not isinstance(target, spec):
            raise TypeMatchError(type(target), spec)
        return target

    if isinstance(spec, dict):
        return _handle_dict(target, spec, scope)

    if isinstance(spec, list):
        if not isinstance(target, list):
            raise TypeMatchError(type(target), list)
        if len(spec) != 1:
            raise MatchError("list spec must have exactly one element, got {0}", len(spec))
        result = []
        for item in target:
            result.append(scope[glom](item, spec[0], scope))
        return result

    if isinstance(spec, tuple):
        if not isinstance(target, tuple):
            raise TypeMatchError(type(target), tuple)
        if len(spec) != len(target):
            raise MatchError("tuple length mismatch: expected {0}, got {1}", len(spec), len(target))
        result = []
        for t_item, s_item in zip(target, spec):
            result.append(scope[glom](t_item, s_item, scope))
        return tuple(result)

    if isinstance(spec, set):
        if not isinstance(target, set):
            raise TypeMatchError(type(target), set)
        if len(spec) != 1:
            raise MatchError("set spec must have exactly one element, got {0}", len(spec))
        result = set()
        for item in target:
            result.add(scope[glom](item, list(spec)[0], scope))
        return result

    if isinstance(spec, frozenset):
        if not isinstance(target, frozenset):
            raise TypeMatchError(type(target), frozenset)
        if len(spec) != 1:
            raise MatchError("frozenset spec must have exactly one element, got {0}", len(spec))
        result = frozenset(scope[glom](item, list(spec)[0], scope) for item in target)
        return result

    if hasattr(spec, 'glomit'):
        return scope[glom](target, spec, scope)

    if target == spec:
        return target

    raise MatchError("{0!r} does not match {1!r}", target, spec)
